import{_ as l,c as i,o as a,af as e}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"《說卦傳》簡介","description":"易傳 - 《說卦傳》簡介","frontmatter":{"title":"《說卦傳》簡介","description":"易傳 - 《說卦傳》簡介"},"headers":[],"relativePath":"classics/yizhuan/004.md","filePath":"classics/yizhuan/004.md"}'),t={name:"classics/yizhuan/004.md"};function s(r,p,n,c,_,o){return a(),i("div",null,[...p[0]||(p[0]=[e('<h1 id="《說卦傳》簡介" tabindex="-1">《說卦傳》簡介 <a class="header-anchor" href="#《說卦傳》簡介" aria-label="Permalink to “《說卦傳》簡介”">​</a></h1><p>《說卦傳》主要解說八卦所象徵的各類事物，闡述六十四卦的排列原理和各卦的屬性意義。其功能作用在於輔助占斷吉凶，揭示自然現象和社會現象的變化與相互關係，其要點在於觸類旁通，對於理解爻辭中所出現的各類人事物有著重要參考意義。</p><p>說卦傳</p><p>昔者聖人之作《易》也，幽贊於神明而生蓍，參天兩地而倚數，觀變於陰陽而立卦，發揮於剛柔而生爻，和順於道德而理於義，窮理盡性以至於命。</p><p>昔者聖人之作《易》也，將以順性命之理。是以立天之道曰陰與陽，立地之道曰柔與剛，立人之道曰仁與義。兼三才而兩之，故《易》六畫而成卦。分陰分陽，迭用柔剛，故《易》六位而成章。</p><p>天地定位，山澤通氣，雷風相薄，水火不相射，八卦相錯。數往者順，知來者逆，是故《易》逆數也。</p><p>雷以動之，風以散之，雨以潤之，日以烜之，艮以止之，兌以說之，乾以君之，坤以藏之。</p><p>帝出乎震，齊乎巽，相見乎離，致役乎坤，說言乎兌，戰乎乾，勞乎坎，成言乎艮。萬物出乎震，震東方也。齊乎巽，巽東南也；齊也者，言萬物之絜齊也。</p><p>離也者，明也，萬物皆相見，南方之卦也，聖人南面而聽天下，嚮明而治，蓋取諸此也。坤也者，地也，萬物皆致養焉，故曰：致役乎坤。兌，正秋也，萬物之所說也，故曰：說言乎兌。戰乎乾，乾西北之卦也，言陰陽相薄也。坎者水也，正北方之卦也，勞卦也，萬物之所歸也，故曰：勞乎坎。艮，東北之卦也。萬物之所成終而成始也，故曰：成言乎艮。</p><p>神也者，妙萬物而為言者也。動萬物者莫疾乎雷，撓萬物者莫疾乎風，躁萬物者莫&amp;乎火，說萬物者莫說乎澤，潤萬物者莫潤乎水，終萬物始萬物者莫盛乎艮。故水火相逮，雷風不相悖，山澤通氣，然後能變化，既成萬物也。</p><p>乾，健也。坤，順也。震，動也。巽，入也。坎，陷也。離，麗也。艮，止也。兌，說也。</p><p>乾為馬，坤為牛，震為龍，巽為雞，坎為豕，離為雉，艮為狗，兌為羊。</p><p>乾為首，坤為腹，震為足，巽為股，坎為耳，離為目，艮為手，兌為口。</p><p>乾，天也，故稱乎父。坤，地也，故稱乎母。震一索而得男，故謂之長男。</p><p>巽一索而得女，故謂之長女。坎再索而得男。故謂之中男。離謂之中男。離再索而得女，故謂之中女。艮三索而得男，故謂之少男。兌三索而得女，故謂之少女。</p><p>乾為天，為圓，為君，為父，為玉，為金，為寒，為冰，為大赤，為良馬，為老馬，為瘠馬，為駁馬，為木果。</p><p>坤為地，為母，為布，為釜，為吝嗇，為均，為子母牛，為大輿，為文，為眾，為柄，其於地也為黑。</p><p>震為雷，為龍，為玄黃，為旉，為大途，為長子，為決躁，為蒼筤竹，為萑葦。其於馬也，為善鳴，為馵足，為作足，為的顙。其於稼也，為反生。其究為健，為蕃鮮。</p><p>巽為木，為風，為長女，為繩直，為工，為白，為長，為高，為進退，為不果，為臭。其於人也，為寡發，為廣顙，為多白眼，為近利市三倍，其究為躁卦。</p><p>坎為水，為溝瀆，為隱伏，為矯輮，為弓輪。其於人也，為加憂，為心病，為耳痛，為血卦，為赤。其於馬也，為美脊，為亟心，為下首，為薄蹄，為曳。</p><p>其於輿也，為多眚，為通，為月，為盜。其於木也，為堅多心。</p><p>離為火，為日，為電，為中女，為甲冑，為戈兵。其於人也，為大腹。為乾卦，為鱉，為蟹，為蠃，為蚌，為龜。其於木也，為科上槁。</p><p>艮為山，為徑路，為小石，為門闕，為果蓏，為閽寺，為指，為狗，為鼠，為黔喙之屬。其於木也，為堅多節。</p><p>兌為澤，為少女，為巫，為口舌，為毀折，為附決。其於地也，為剛滷。為妾，為羊。</p><p>主要記述並解說乾、坤、艮、兌、坎、離、震、巽八經卦所象徵的各類事物，以及闡述六十四卦卦序排列原理和各卦的屬性意義，以輔助占斷吉凶。</p><p>八卦類象是將宇宙間萬事萬物分為八類，以八卦為標準進行劃分。為了更好地理解和記憶八卦類象，可以採用以下方法：</p><ul><li>家庭角色法 ：將世界看做一個家庭，每個八卦代表不同的家庭成員或角色。例如，乾卦代表父親（陽剛、權威），坤卦代表母親（柔順、包容），震卦代表長子（陽剛、有力），巽卦代表長女（柔順、入內），坎卦代表中男（中堅力量、險難），離卦代表中女（光明、美麗），艮卦代表少男（靜止、少動），兌卦代表少女（喜悅、說話）。</li></ul><p>家庭角色法 ：</p><ul><li><p>將世界看做一個家庭，每個八卦代表不同的家庭成員或角色。例如，乾卦代表父親（陽剛、權威），坤卦代表母親（柔順、包容），震卦代表長子（陽剛、有力），巽卦代表長女（柔順、入內），坎卦代表中男（中堅力量、險難），離卦代表中女（光明、美麗），艮卦代表少男（靜止、少動），兌卦代表少女（喜悅、說話）。</p></li><li><p>三爻觀察法 ：觀察八卦中的三爻。當卦中三爻相同時，陽為男，陰為女；三爻不同時，數量最少的爻代表性別。例如，乾卦三個陽爻代表男性，坤卦三個陰爻代表女性；震卦一個陽爻在下代表長子，巽卦一個陰爻在下代表長女，以此類推。</p></li></ul><p>三爻觀察法 ：</p><ul><li><p>觀察八卦中的三爻。當卦中三爻相同時，陽為男，陰為女；三爻不同時，數量最少的爻代表性別。例如，乾卦三個陽爻代表男性，坤卦三個陰爻代表女性；震卦一個陽爻在下代表長子，巽卦一個陰爻在下代表長女，以此類推。</p></li><li><p>口訣記憶法 ：使用口訣幫助記憶八卦符號和類象。如“乾三連，坤六斷，震仰盂，艮覆碗，離中虛，坎中滿，兌上缺，巽下斷”。這些口訣簡潔明瞭，便於記憶八卦的基本形態和特徵。</p></li></ul><p>口訣記憶法 ：</p><ul><li><p>使用口訣幫助記憶八卦符號和類象。如“乾三連，坤六斷，震仰盂，艮覆碗，離中虛，坎中滿，兌上缺，巽下斷”。這些口訣簡潔明瞭，便於記憶八卦的基本形態和特徵。</p></li><li><p>聯想記憶法 ：將八卦符號與具體事物進行聯想，以增強記憶效果。例如，乾卦代表天，可以聯想到廣闊的藍天和無限的可能；坤卦代表地，可以聯想到肥沃的土地和孕育萬物的母親；震卦代表雷，可以聯想到雷鳴電閃的震撼力量；等等。</p></li></ul><p>聯想記憶法 ：</p><ul><li><p>將八卦符號與具體事物進行聯想，以增強記憶效果。例如，乾卦代表天，可以聯想到廣闊的藍天和無限的可能；坤卦代表地，可以聯想到肥沃的土地和孕育萬物的母親；震卦代表雷，可以聯想到雷鳴電閃的震撼力量；等等。</p></li><li><p>應用實踐法 ：在實際應用中加深理解和記憶。通過占卜、風水、中醫等領域的學習和實踐，將八卦類象的知識與現實生活相結合，提高學習的趣味性和實用性。</p></li></ul><p>應用實踐法 ：</p><ul><li>在實際應用中加深理解和記憶。通過占卜、風水、中醫等領域的學習和實踐，將八卦類象的知識與現實生活相結合，提高學習的趣味性和實用性。</li></ul>',37)])])}const m=l(t,[["render",s]]);export{d as __pageData,m as default};
